How can I retrieve and display data from a SQL database using Swift, specifically looking for examples of roses and love symbolism in poetry?
Here is an example Swift code to query the database and display the results in a table view:
```
import UIKit
import SQLite3
class ViewController: UIViewController, UITableViewDataSource, UITableViewDelegate {
    var db: OpaquePointer?
    var poems = [Poem]()
    @IBOutlet weak var tableView: UITableView!
    override func viewDidLoad() {
        super.viewDidLoad()
        let fileUrl = try!
            FileManager.default.url(for: .documentDirectory, in: .userDomainMask, appropriateFor: nil, create: false)
            .appendingPathComponent("PoemsDatabase.sqlite")
        if sqlite3_open(fileUrl.path, &db) != SQLITE_OK {
            print("Error opening database")
        }
        let createTableQuery = "CREATE TABLE IF NOT EXISTS poems (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, content TEXT)"
        if sqlite3_exec(db, createTableQuery, nil, nil, nil) != SQLITE_OK {
            print("Error creating table")
        }
        let insert1 = "INSERT INTO poems (title, content) VALUES ('Poem 1', 'Roses are red, violets are blue, sugar is sweet, and so are you.')"
        let insert2 = "INSERT INTO poems (title, content) VALUES ('Poem 2', 'Love is a rose, delicate and fair, tender yet sharp, with thorns that beware.')"
        let insert3 = "INSERT INTO poems (title, content) VALUES ('Poem 3', 'A single rose, a token of love, given with care, from heaven above.')"
        if sqlite3_exec(db, insert1, nil, nil, nil) != SQLITE_OK {
            print("Error inserting poem 1")
        }
        if sqlite3_exec(db, insert2, nil, nil, nil) != SQLITE_OK {
            print("Error inserting poem 2")
        }
        if sqlite3_exec(db, insert3, nil, nil, nil) != SQLITE_OK {
            print("Error inserting poem 3")
        }
        getData()
    }
    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return poems.count
    }
    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "cell", for: indexPath)
        let poem = poems[indexPath.row]
        cell.textLabel?.text = poem.title
        cell.detailTextLabel?.text = poem.content
        return cell
    }
    func getData() {
        poems.removeAll()
        let query = "SELECT * FROM poems WHERE content LIKE '%rose%' AND content LIKE '%love%'"
        var stmt: OpaquePointer?
        if sqlite3_prepare(db, query, -1, &stmt, nil) != SQLITE_OK {
            print("Error preparing query")
            return
        }
        while sqlite3_step(stmt) == SQLITE_ROW {
            let id = sqlite3_column_int(stmt, 0)
            let title = String(cString: sqlite3_column_text(stmt, 1))
            let content = String(cString: sqlite3_column_text(stmt, 2))
            let poem = Poem(id: Int(id), title: title, content: content)
            poems.append(poem)
        }
        self.tableView.reloadData()
    }
}
struct Poem {
    var id: Int
    var title: String
    var content: String
}
``` 
