```
func getData() {
    poems.removeAll()
    let query = "SELECT MAX(id), title, content FROM poems WHERE content LIKE '%rose%' AND content LIKE '%love%' GROUP BY title"
    var stmt: OpaquePointer?
    if sqlite3_prepare(db, query, -1, &stmt, nil) != SQLITE_OK {
        print("Error preparing query")
        return
    }
    while sqlite3_step(stmt) == SQLITE_ROW {
        let id = sqlite3_column_int(stmt, 0)
        let title = String(cString: sqlite3_column_text(stmt, 1))
        let content = String(cString: sqlite3_column_text(stmt, 2))
        let poem = Poem(id: Int(id), title: title, content: content)
        poems.append(poem)
    }
    self.tableView.reloadData()
}
```
In the modified `query`, we use the `MAX(id)` function to retrieve the last instance of each poem, and `GROUP BY title` to group the results by the `title` column. This will ensure that only the last instance of each poem with the specified content is retrieved.

