        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);
        CURLcode res = curl_easy_perform(curl);
        if(res == CURLE_OK) {
            Json::Value response;
            Json::Reader reader;
            bool parsed = reader.parse(curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response));
            if(parsed && response == 200) {
                parsed = reader.parse(curl_easy_getinfo(curl, CURLINFO_BODY_CONTENT, &response));
                if(parsed) {
                    Json::Value adjs = response["positive_adjectives"];
                    for(int i = 0; i < adjs.size(); i++) {
                        adjectives.push_back(adjs[i].asString());
                    }
                }
            }
        }
        curl_easy_cleanup(curl);
    }
    return adjectives;
}
