\begin{algorithm}
\caption{Family Reunion Planning Algorithm}
\label{alg:family-reunion}
\begin{algorithmic}[1]
\State $attendees \gets$ list of attendees and their information
\State $activities \gets$ list of available activities and their details
\State $groups \gets$ empty list of groups
