Sure, here's a Swift code that can identify alliteration and count the number of syllables with the same initial consonant sound:
```swift
func countAlliterationAndSyllables(_ passage: String) -> (alliteration: String?, syllables: [Int]) {
    let words = passage.lowercased().components(separatedBy: .whitespacesAndNewlines)
    var alliteration: String?
    var syllables: [Int] = []
    var prevConsonant: Character?
    for word in words {
        let firstLetter = word.first ?? " "
        if let consonant = firstLetter.isConsonant ? firstLetter : nil {
            if consonant == prevConsonant {
                if alliteration == nil {
                    alliteration = "\(prevConsonant!)\(word)"
                }
            } else {
                prevConsonant = consonant
                alliteration = nil
            }
        } else {
            prevConsonant = nil
            alliteration = nil
        }
        syllables.append(countSyllables(word))
    }
    return (alliteration, syllables)
}
func countSyllables(_ word: String) -> Int {
    let vowels: Set<Character> = ["a", "e", "i", "o", "u", "y"]
    var syllableCount = 0
    var prevChar: Character?
    for char in word {
        if vowels.contains(char) && (prevChar == nil || !vowels.contains(prevChar!)) {
            syllableCount += 1
        }
        prevChar = char
    }
    if let lastChar = word.last, lastChar == "e" {
        syllableCount -= 1
    }
    return max(syllableCount, 1)
}
extension Character {
    var isConsonant: Bool {
        return !["a", "e", "i", "o", "u"].contains(lowercased())
    }
}
```
