```csharp
using System;
class Program
{
    static void Main(string[] args)
    {
        string[] words = { "BOOK", "HAPPY", "CLEAN", "KIND", "BRAVE" };
        Console.WriteLine("\\begin{tabular}{|c|c|c|}");
        Console.WriteLine("\\hline");
        Console.WriteLine("Word & Formula 1 & Formula 2 \\\\");
        Console.WriteLine("\\hline");
        foreach (string word in words)
        {
            string antonym1, antonym2;
            if ("AEIOU".Contains(word[0]))
            {
                antonym1 = "in" + SwapConsonantsAndVowels(word) + "able";
                antonym2 = "in" + word.Substring(1) + "able";
            }
            else
            {
                antonym1 = "un" + SwapConsonantsAndVowels(word) + "able";
                antonym2 = "un" + word.Substring(1) + "able";
            }
            Console.WriteLine($"{word} & {antonym1} & {antonym2} \\\\");
            Console.WriteLine("\\hline");
        }
        Console.WriteLine("\\end{tabular}");
    }
    static string SwapConsonantsAndVowels(string word)
    {
        char[] vowels = { 'A', 'E', 'I', 'O', 'U' };
        string consonants = "";
        string swapped = "";
        foreach (char c in word)
        {
            if (vowels.Contains(c))
            {
                swapped += consonants[0];
                consonants = consonants.Substring(1);
            }
            else
            {
                consonants += c;
            }
        }
        return swapped + consonants;
    }
}
